import os
from typing import Any, Dict, List, Optional, Union

import requests


class DeepgramTranscriptionError(Exception):
    pass


def transcribe_with_timestamps(
    audio: Union[str, bytes],
    *,
    api_key: Optional[str] = None,
    model: str = "nova-2",
    language: Optional[str] = None,
    granularity: str = "word",
    mimetype: str = "audio/wav",
    smart_format: bool = True,
    punctuate: bool = True,
    diarize: bool = False,
) -> List[Dict[str, Any]]:
    api_key = api_key or os.environ.get("DEEPGRAM_API_KEY")
    if not api_key:
        raise ValueError("Missing Deepgram API key. Set DEEPGRAM_API_KEY or pass api_key.")

    if granularity not in {"word", "segment"}:
        raise ValueError("granularity must be 'word' or 'segment'")

    url = "https://api.deepgram.com/v1/listen"
    params: Dict[str, Any] = {
        "model": model,
        "smart_format": str(smart_format).lower(),
        "punctuate": str(punctuate).lower(),
        "diarize": str(diarize).lower(),
    }
    if language:
        params["language"] = language

    headers = {
        "Authorization": f"Token {api_key}",
    }

    if isinstance(audio, bytes):
        headers["Content-Type"] = mimetype
        response = requests.post(url, headers=headers, params=params, data=audio, timeout=300)
    elif isinstance(audio, str):
        with open(audio, "rb") as f:
            headers["Content-Type"] = mimetype
            response = requests.post(url, headers=headers, params=params, data=f, timeout=300)
    else:
        raise TypeError("audio must be a file path or bytes")

    if response.status_code >= 400:
        raise DeepgramTranscriptionError(
            f"Deepgram API error {response.status_code}: {response.text}"
        )

    payload = response.json()

    try:
        channel = payload["results"]["channels"][0]
        alternative = channel["alternatives"][0]
    except (KeyError, IndexError, TypeError) as e:
        raise DeepgramTranscriptionError(f"Unexpected Deepgram response format: {payload}") from e

    if granularity == "word":
        words = alternative.get("words", [])
        return [
            {
                "text": w.get("word"),
                "start": w.get("start"),
                "end": w.get("end"),
                "confidence": w.get("confidence"),
                "speaker": w.get("speaker"),
                "punctuated_word": w.get("punctuated_word"),
            }
            for w in words
        ]

    paragraphs = (
        alternative.get("paragraphs", {}).get("paragraphs", [])
        if isinstance(alternative.get("paragraphs"), dict)
        else []
    )
    if paragraphs:
        segments: List[Dict[str, Any]] = []
        for p in paragraphs:
            sentences = p.get("sentences", [])
            for s in sentences:
                segments.append(
                    {
                        "text": s.get("text"),
                        "start": s.get("start"),
                        "end": s.get("end"),
                    }
                )
        if segments:
            return segments

    transcript = alternative.get("transcript", "")
    words = alternative.get("words", [])
    if not words:
        return [{"text": transcript, "start": None, "end": None}]

    return [
        {
            "text": transcript,
            "start": words[0].get("start"),
            "end": words[-1].get("end"),
        }
    ]
